INSERT INTO `terms_conditions` (`id`, `school_id`, `title`, `content`, `version`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 5, 'School Terms and Conditions', '<p>sdvvbsfvsvfsvfv</p>', '1.0', 0, '2025-06-09 00:08:37', '2025-06-12 05:00:44'),
(2, 5, 'School Terms and Conditions', '<p>At enim hic etiam dolore. Dulce amarum, leve asperum, prope longe, stare movere, quadratum rotundum. At certe gravius. Nullus est igitur cuiusquam dies natalis. Paulum, cum regem Persem captum adduceret, eodem flumine invectio?<br><br>Quare hoc videndum est, possitne nobis hoc ratio philosophorum dare.</p>\r\n<p>Sed finge non solum callidum eum, qui aliquid improbe faciat, verum etiam praepotentem, ut Est autem officium, quod ita factum est, ut eius facti probabilis ratio reddi possit.</p>', '1.0', 0, '2025-06-09 00:10:26', '2025-06-12 05:00:44'),
(3, 5, 'School Terms and Conditions', '<p>At enim hic etiam dolore. Dulce amarum, leve asperum, prope longe, stare movere, quadratum rotundum. At certe gravius. Nullus est igitur cuiusquam dies natalis. Paulum, cum regem Persem captum adduceret, eodem flumine invectio?<br><br>Quare hoc videndum est, possitne nobis hoc ratio philosophorum dare.</p>\r\n<p>Sed finge non solum callidum eum, qui aliquid improbe faciat, verum etiam praepotentem, ut Est autem officium, quod ita factum est, ut eius facti probabilis ratio reddi possit.</p>', '1.0', 1, '2025-06-12 05:00:44', '2025-06-12 05:00:44'),
(4, 10, 'Demo', '<h1>Word Document Uploaded: bmdu.docx</h1><p>Please note that this is a Word document. The content may include formatting that is not preserved in this text representation.</p><p>You may want to manually copy and paste the content from the Word document into the editor for better formatting.</p>', '1.0', 0, '2025-07-25 11:32:19', '2025-08-19 05:05:26'),
(5, 10, 'demo 2', '<h1>PDF File Uploaded: ThirdEye_Application_Documentation.pdf</h1><p>Please note that this is a PDF file. The content may include formatting that is not preserved in this text representation.</p><p>You may want to manually copy and paste the content from the PDF into the editor for better formatting.</p>', '2.0', 0, '2025-07-25 11:33:28', '2025-08-19 05:05:26'),
(6, 10, 'demo 2', '<h1>PDF File Uploaded: ThirdEye_Application_Documentation.pdf</h1>\r\n<p>Please note that this is a PDF file. The content may include formatting that is not preserved in this text representation.</p>\r\n<p>You may want to manually copy and paste the content from the PDF into the editor for better formatting. dfdfd</p>', '2.0', 0, '2025-07-26 06:51:16', '2025-08-19 05:05:26'),
(7, 10, 'demo 2', '<h1>PDF File Uploaded: ThirdEye_Application_Documentation.pdf</h1>\r\n<p>Please note that this is a PDF file. The content may include formatting that is not preserved in this text representation.</p>\r\n<p>You may want to manually copy and paste the content from the PDF into the editor for better formatting. dfdfd nn</p>', '2.0', 0, '2025-07-26 06:52:08', '2025-08-19 05:05:26'),
